#include <iostream>
#include <vector>
using namespace std;

int getResult(int a, int b, int l, int r) {
    if ((r - l + 1) > 2 * (a + b))
        return (a <= b) ? a + 1 : (2 * a - b);

    int size = 3 * (a + b) + 1;
    vector<int> patternArr(size, 0);
    int lastVal = 0;

    for (int i = 1; i <= a; i++) {
        patternArr[i] = i;
        lastVal = i;
    }

    for (int i = a + 1; i <= a + b; i++) {
        patternArr[i] = lastVal;
    }

    auto containsInRange = [&](const vector<int>& arr, int val, int start, int end) {
        for (int i = start; i <= end; i++) {
            if (arr[i] == val)
                return true;
        }
        return false;
    };

    for (int i = a + b + 1; i <= a + b + a; i++) {
        int count = 1;
        while (containsInRange(patternArr, count, a + b - a + 1, i - 1))
            count++;
        patternArr[i] = count;
        lastVal = patternArr[i];
    }

    for (int i = a + b + a + 1; i <= a + b + a + b; i++) {
        patternArr[i] = lastVal;
    }

    for (int i = 2 * (a + b) + 1; i <= 3 * (a + b); i++) {
        patternArr[i] = patternArr[i - (a + b)];
    }

    vector<int> coverageArray(25, 0);
    int startIdx = l % (a + b);
    if (startIdx == 0) startIdx += a + b;
    int endIdx = r - l + startIdx;
    if (endIdx < startIdx) endIdx += a + b;

    for (int i = startIdx; i <= endIdx; i++) {
        coverageArray[patternArr[i]] = 1;
    }

    int countCoverage = 0;
    for (int i = 1; i <= 24; i++)
        countCoverage += coverageArray[i];

    return countCoverage;
}

int main() {
    int a, b, l, r;
    cin >> a >> b >> l >> r;
    cout << getResult(a, b, l, r) << endl;
    return 0;
}

